package com.servicerca.controller;import com.servicerca.dto.user.TradeResponse;import com.servicerca.mapper.ApiMapper;import com.servicerca.repository.TradeRepository;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/v1/trades")public class TradeController{private final TradeRepository repository;private final ApiMapper mapper;public TradeController(TradeRepository r,ApiMapper m){repository=r;mapper=m;}@GetMapping public ResponseEntity<List<TradeResponse>>getAll(){return ResponseEntity.ok(repository.findAll().stream().map(mapper::toTradeResponse).toList());}}
